import re
import collections
from taf.analyzer.iperf_throughput.cell import (IDCell, IntervalCell, TransferCell, BandwidthCell,
                                                JitterCell, LostTotalDatagramsCell, RetrCell,
                                                CwndCell, BitrateCell, TotalDatagramsCell)
from taf.analyzer.iperf_throughput.entry import Entry, RawEntry


class Connection(object):
    def __init__(self, connection_info_dict):
        self._info_dict = connection_info_dict
        for key, value in connection_info_dict.items():
            setattr(self, key, value)

    def to_dict(self):
        return self._info_dict


class ColumnFinder(object):
    def __init__(self):
        self._all_candidate_cell_classes = [IDCell, IntervalCell, TransferCell, BandwidthCell, BitrateCell,
                                            JitterCell, LostTotalDatagramsCell, TotalDatagramsCell, RetrCell, CwndCell]

    def find(self, line):
        cell_clses = []
        total_datagram_cell_need_skip = False
        for cell_cls in self._all_candidate_cell_classes:
            if cell_cls.column() in line:
                if cell_cls is LostTotalDatagramsCell:
                    total_datagram_cell_need_skip = True
                if total_datagram_cell_need_skip and cell_cls is TotalDatagramsCell:
                    continue
                cell_clses.append(cell_cls)
        return cell_clses


class HeaderFactory(object):

    CONNECTION_ID_ATTRIBUTE_NAME = "connection_id"

    def create(self, lines):

        connections = self._find_connections(lines)
        virtual_sum_connection = self._create_virtual_sum_connection(connections)
        if virtual_sum_connection:
            connections.append(virtual_sum_connection)

        return DataHeader(connections={connection.connection_id: connection for connection in connections}
                          ) if connections else None

    def _find_connections(self, raw_lines):
        """
        client information at the server side should be like:
        ------------------------------------------------------------
        [  3] local 10.44.35.224 port 53892 connected with 10.47.55.157 port 5001
        [  5] local 10.44.35.224 port 50006 connected with 10.47.55.164 port 40151
        [ ID] Interval       Transfer     Bandwidth        Jitter   Lost/Total Datagrams
        """
        upper_bound_pattern = '-' * 20
        content = ''
        for i in range(0, len(raw_lines) - 1)[::-1]:  # exclude column header
            content = content + raw_lines[i]
            if upper_bound_pattern in raw_lines[i]:
                break

        connection_info_list = re.findall(self.pattern, content)
        return [Connection(dict(zip(self.connection_attribute_names, connection_info)))
                for connection_info in connection_info_list]

    def _create_virtual_sum_connection(self, real_connections):
        if not real_connections:
            return None

        if len(real_connections) <= 1:
            return None

        attribute_count = len(self.connection_attribute_names)
        init_data = [''] * attribute_count
        virtual_sum_connection = dict(zip(self.connection_attribute_names, init_data))
        virtual_sum_connection[self.CONNECTION_ID_ATTRIBUTE_NAME] = 'SUM'
        return Connection(virtual_sum_connection)

    @property
    def connection_attribute_names(self):
        raise NotImplementedError()

    @property
    def pattern(self):
        return ''

    def is_connection_info(self, line):
        result = re.match(self.pattern, line)
        return True if result else False


class Iperf2HeaderFactory(HeaderFactory):
    @property
    def pattern(self):
        return r'\[\s*(\d+)]\slocal\s(\d+\.\d+\.\d+\.\d+)\sport\s(\d+)' \
               r'\sconnected\swith\s(\d+\.\d+\.\d+\.\d+)\sport\s(\d+)'


class Iperf2ServerSideHeaderFactory(Iperf2HeaderFactory):
    @property
    def connection_attribute_names(self):
        return [self.CONNECTION_ID_ATTRIBUTE_NAME, 'server_addr', 'server_port', 'client_addr', 'client_port']


class Iperf2ClientSideHeaderFactory(Iperf2HeaderFactory):
    @property
    def connection_attribute_names(self):
        return [self.CONNECTION_ID_ATTRIBUTE_NAME, 'client_addr', 'client_port', 'server_addr', 'server_port']


class Iperf3HeaderFactory(HeaderFactory):
    @property
    def pattern(self):
        return r'\[\s*(\d+)]\slocal\s(\d+\.\d+\.\d+\.\d+)\sport\s(\d+)' \
               r'\sconnected\sto\s(\d+\.\d+\.\d+\.\d+)\sport\s(\d+)'


class Iperf3ClientSideHeaderFactory(Iperf3HeaderFactory):
    @property
    def connection_attribute_names(self):
        return [self.CONNECTION_ID_ATTRIBUTE_NAME, 'client_addr', 'client_port', 'server_addr', 'server_port']


class Iperf3ServerSideHeaderFactory(Iperf3HeaderFactory):
    @property
    def connection_attribute_names(self):
        return [self.CONNECTION_ID_ATTRIBUTE_NAME, 'client_addr', 'client_port', 'server_addr', 'server_port']


class DataHeader(object):
    def __init__(self, connections):
        self._connections = connections

    @property
    def connections(self):
        return self._connections


class IperfDataRowFactory(object):
    def __init__(self, separator=None):
        self._separator = separator or r"\s{1,}"
        self._data_cell_classes = []
        self._simple_data_cell_classes = []

    def update(self, cell_classes):
        """
        _simple_data_cell_classes nly support the first 4 columns to adapt later columns missing like jitter
        usually include ID     Interval       Transfer     Bandwidth
        """
        self._data_cell_classes = cell_classes
        self._simple_data_cell_classes = cell_classes[:4]

    @property
    def data_cell_classes(self):
        return self._data_cell_classes

    @staticmethod
    def _create_entry(line, cell_classes, pattern):
        values = re.match(pattern, line.strip())
        if not values:
            entry = RawEntry(raw=line)
            return entry
        value_dict = values.groupdict()
        entry = Entry()
        for cell_cls in cell_classes:
            entry.add_cell(cell_cls(**value_dict))
        return entry

    def create(self, line):
        entry = self._create_entry(line, self.data_cell_classes, self.pattern)
        if isinstance(entry, RawEntry) and 'SUM' in line:
            entry = self._create_entry(line, self._simple_data_cell_classes, self.simple_pattern)
        return entry

    @property
    def separator(self):
        return self._separator

    @property
    def pattern(self):
        partial_patterns = [cell_cls.partial_pattern() for cell_cls in self.data_cell_classes]
        return self._separator.join(partial_patterns)

    @property
    def simple_pattern(self):
        """
        only support the first 4 columns to adapt later columns missing like jitter
        usually include ID     Interval       Transfer     Bandwidth
        """
        partial_patterns = [cell_cls.partial_pattern() for cell_cls in self._simple_data_cell_classes]
        return self._separator.join(partial_patterns)


class Iperf2DataRowFactory(IperfDataRowFactory):
    def __init__(self, separator=None):
        super(Iperf2DataRowFactory, self).__init__(separator=separator)

    @property
    def pattern(self):
        partial_patterns = [cell_cls.partial_pattern() for cell_cls in self.data_cell_classes]
        return "{}{}{}".format('^', self._separator.join(partial_patterns), '$')

    @property
    def simple_pattern(self):
        partial_patterns = [cell_cls.partial_pattern() for cell_cls in self._simple_data_cell_classes]
        return "{}{}".format('^', self._separator.join(partial_patterns))


class Iperf3ServerSideDataRowFactory(IperfDataRowFactory):
    def __init__(self, separator=None):
        super(Iperf3ServerSideDataRowFactory, self).__init__(separator=separator)

    @property
    def pattern(self):
        partial_patterns = [cell_cls.partial_pattern() for cell_cls in self.data_cell_classes]
        return "{}{}{}{}".format('^', self._separator.join(partial_patterns), r"(\s*receiver)?", '$')

    @property
    def simple_pattern(self):
        return self.pattern


class Iperf3UDPClientSideDataRowFactory(IperfDataRowFactory):
    def __init__(self, separator=None):
        super(Iperf3UDPClientSideDataRowFactory, self).__init__(separator=separator)

    @property
    def pattern(self):
        partial_patterns = [cell_cls.partial_pattern() for cell_cls in self.data_cell_classes]
        return "{}{}{}".format('^', self._separator.join(partial_patterns), '$')

    @property
    def simple_pattern(self):
        return self.pattern


class Iperf3TCPClientSideDataRowFactory(IperfDataRowFactory):
    def __init__(self, separator=None):
        super(Iperf3TCPClientSideDataRowFactory, self).__init__(separator=separator)

    @property
    def pattern(self):
        partial_patterns = [cell_cls.partial_pattern()
                            for cell_cls in [IDCell, IntervalCell, TransferCell, BandwidthCell, RetrCell]]
        required_cells_part_pattern = self.separator.join(partial_patterns)
        result_pattern = '^' + required_cells_part_pattern + r'\s*({})?(\s*sender)?'.format(
            CwndCell.partial_pattern()) + '$'
        return result_pattern

    @property
    def simple_pattern(self):
        return self.pattern


class Reader(object):
    def __enter__(self):
        raise NotImplementedError()

    def __exit__(self, exc_type, exc_val, exc_tb):
        raise NotImplementedError()

    @property
    def log_entries(self):
        raise NotImplementedError()


class FileReader(Reader):
    def __init__(self, log):
        self._log = log
        self._fobj = None

    def __enter__(self):
        self._fobj = open(self._log, "rb")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self._fobj:
            self._fobj.close()
            self._fobj = None


class IperfLogReader(FileReader):

    Factories = collections.namedtuple('Factories', 'header data')

    def __init__(self, log, header_factory, data_factory):
        super(IperfLogReader, self).__init__(log)
        self._header_factory = header_factory
        self._data_factory = data_factory
        self._column_finder = ColumnFinder()

    def _try_header_end_matching(self, line):
        cell_classes = self._column_finder.find(line)
        if not cell_classes:
            return None

        self._data_factory.update(cell_classes)
        return self.Factories(header=self._header_factory, data=self._data_factory)

    @property
    def log_entries(self):
        return self

    def __iter__(self):

        lines_including_header = []
        factories = None
        header = None
        for line in self._fobj:
            line = line.decode()

            if not factories:
                factories = self._try_header_end_matching(line)
                lines_including_header.append(line)
                if factories:
                    header = factories.header.create(lines_including_header)
                continue
            else:
                entry = factories.data.create(line)
                if isinstance(entry, RawEntry) and factories.header.is_connection_info(line):
                    return
                entry.header = header
                yield entry
